export function mountPrototype(root) {
const controller = new AbortController();
const icons={compass:'<circle cx="12" cy="12" r="9"/><path d="m15.6 8.4-2.3 4.9-4.9 2.3 2.3-4.9z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',chat:'<path d="M21 11.5a8.4 8.4 0 0 1-9 8.5 9 9 0 0 1-4-.9L3 21l1.9-5A9 9 0 1 1 21 11.5Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',plus:'<path d="M12 5v14M5 12h14"/>',pin:'<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',back:'<path d="m19 12-14 0m6-6-6 6 6 6"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',check:'<path d="m4 12 5 5L20 6"/>',flag:'<path d="M5 21V4m0 1c6-4 8 4 15 0v10c-7 4-9-4-15 0"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const seed=[
 {id:1,category:'Fitness',title:'Saturday morning swim at Silver Springs',venue:'Silver Springs Hotel pool, Bugolobi',date:'Sat, 3 Oct',time:'10:00 AM',spots:1,size:2,host:'Maya K.',initials:'MK',tone:'pink',intro:'Getting back into swimming and would love company for easy laps. Beginners welcome. We can grab a juice afterwards.',bring:'Swimwear, towel and pool entry fee',meet:'At the café entrance beside the pool',status:'open'},
 {id:2,category:'Outings',title:'Coffee and a quiet work session',venue:'Endiro Coffee, Kisementi',date:'Sun, 4 Oct',time:'2:30 PM',spots:2,size:4,host:'David O.',initials:'DO',tone:'green',intro:'Bring a laptop or notebook. Work for 90 minutes, then take a proper coffee break together.',bring:'Laptop or notebook; buy your own drink',meet:'Inside, at the long table near the window',status:'open'},
 {id:3,category:'Fitness',title:'Try a beginner circuit class together',venue:'The Cube Fitness, Kololo',date:'Mon, 5 Oct',time:'6:00 PM',spots:1,size:2,host:'Brenda N.',initials:'BN',tone:'',intro:'First circuit class for both of us? Let’s arrive a little early and figure it out together.',bring:'Workout clothes, water and class fee',meet:'At the front desk, 15 minutes before class',status:'open'},
 {id:4,category:'Outings',title:'A slow walk through the botanical gardens',venue:'Entebbe Botanical Gardens',date:'Sat, 10 Oct',time:'9:00 AM',spots:3,size:5,host:'Aisha M.',initials:'AM',tone:'pink',intro:'An easy morning walk, fresh air and good conversation. We’ll stay on the main paths.',bring:'Comfortable shoes, water and entry fee',meet:'At the main entrance ticket office',status:'open'},
 {id:5,category:'Learning',title:'Sketch and sip at an art workshop',venue:'The Artfield, Ntinda',date:'Sun, 11 Oct',time:'11:00 AM',spots:2,size:3,host:'Joel T.',initials:'JT',tone:'green',intro:'No drawing skills required. I want to try the weekend workshop and it would be easier to walk in with someone.',bring:'Workshop fee and curiosity',meet:'Outside the studio entrance',status:'open'}
];
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const saved=(()=>{try{return JSON.parse(localStorage.getItem('along-demo'))}catch{return null}})();
const state={plans:saved?.plans||seed,requests:saved?.requests||[],joined:saved?.joined||[],hostRequests:saved?.hostRequests||[],messages:saved?.messages||{1:[{mine:false,text:'Hi! The pool opens at 9, so 10 should be nice and calm.',time:'Yesterday'}]},checkins:saved?.checkins||[],completed:saved?.completed||[],screen:'explore',detail:1,filter:'All',query:'',planTab:'Upcoming',chatId:1,toast:''};
function save(){localStorage.setItem('along-demo',JSON.stringify({plans:state.plans,requests:state.requests,joined:state.joined,hostRequests:state.hostRequests,messages:state.messages,checkins:state.checkins,completed:state.completed}))}
function toast(msg){state.toast=msg;render();setTimeout(()=>{state.toast='';render()},3000)}
function nav(screen){state.screen=screen;window.scrollTo(0,0);render()}
function plan(id){return state.plans.find(p=>p.id===Number(id))}
function avatar(p,small=false){return `<span class="avatar ${p.tone||''} ${small?'small':''}" aria-label="${safe(p.host)}">${safe(p.initials)}</span>`}
function navButton(screen,label,ico){return `<button class="${state.screen===screen?'active':''}" data-nav="${screen}">${icon(ico)}<span>${label}</span></button>`}
function chrome(body){return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">a</span>along</div><nav class="nav">${navButton('explore','Explore','compass')}${navButton('plans','My plans','calendar')}${navButton('chat','Messages','chat')}${navButton('profile','Profile','user')}</nav><div class="sidebar-bottom"><div class="mini-profile"><span class="avatar">YO</span><div><strong>You</strong><div class="small muted">Kampala, Uganda</div></div></div></div></aside><main class="content"><header class="topbar"><div class="location">${icon('pin')} Kampala · demo neighbourhood</div><div class="top-actions"><span class="demo-pill">Interactive concept · sample data</span><button class="button" data-nav="create">${icon('plus')} Make a plan</button></div></header>${body}</main></div><nav class="mobile-nav">${navButton('explore','Explore','compass')}${navButton('plans','My plans','calendar')}<button class="create-nav" data-nav="create">${icon('plus')}<span>Create</span></button>${navButton('chat','Chat','chat')}${navButton('profile','Profile','user')}</nav>${state.toast?`<div class="toast" role="status">${safe(state.toast)}</div>`:''}`}
function card(p){return `<article class="plan-card"><div class="card-top"><span class="category ${p.category.toLowerCase()}">${safe(p.category)}</span><span class="spots">${p.spots} ${p.spots===1?'spot':'spots'} open</span></div><h3>${safe(p.title)}</h3><p>${safe(p.intro)}</p><div class="meta-row"><span>${icon('calendar')}${safe(p.date)} · ${safe(p.time)}</span><span>${icon('pin')}${safe(p.venue)}</span></div><div class="card-bottom"><div class="host-row">${avatar(p,true)}<div><strong>${safe(p.host)}</strong><small>Hosting this plan</small></div></div><button class="card-link" data-detail="${p.id}">View plan →</button></div></article>`}
function explore(){let filtered=state.plans.filter(p=>p.status==='open'&&p.spots>0&&(state.filter==='All'||p.category===state.filter)&&`${p.title} ${p.venue} ${p.category}`.toLowerCase().includes(state.query.toLowerCase()));return `<section class="hero"><div class="hero-copy"><h1>The good stuff happens when you go.</h1><p>Find a person to try that class, take that walk, or finally make that plan with. Small plans, real places, good company.</p><button class="button" data-nav="create">${icon('plus')} Start a plan</button></div><div class="hero-art"><div class="hero-note"><strong>Swimming is easier with someone.</strong><span>Saturday · Bugolobi · 1 spot open</span><div class="note-avatars"><span class="avatar pink small">MK</span><span class="avatar green small">YOU</span></div></div></div></section><div class="page-head"><div><h1>Explore plans</h1><p>Find something you’d like to do around Kampala.</p></div></div><div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Search plans" placeholder="Search activities or places" value="${safe(state.query)}"></label><span class="small-pill">Public places first</span></div><div class="filters">${['All','Fitness','Outings','Learning'].map(x=>`<button class="chip ${state.filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="section-head"><h2>Plans worth leaving home for</h2><span>${filtered.length} available</span></div><div class="plan-grid">${filtered.length?filtered.map(card).join(''):`<div class="empty"><h3>No plans match that search.</h3><p>Try another activity or put your own plan out there.</p><button class="button" data-nav="create">Make a plan</button></div>`}</div>`}
function detail(){let p=plan(state.detail),requested=state.requests.includes(p.id),joined=state.joined.includes(p.id),mine=p.host==='You',incoming=state.hostRequests.includes(p.id);return `<button class="back" data-nav="explore">${icon('back')} Back to explore</button><div class="detail-layout"><article class="panel detail-main"><span class="category ${p.category.toLowerCase()}">${safe(p.category)}</span><h1>${safe(p.title)}</h1><p>${safe(p.intro)}</p><div class="detail-meta"><div>${icon('calendar')}<div><strong>${safe(p.date)} at ${safe(p.time)}</strong><span>Confirm details in chat before you go</span></div></div><div>${icon('pin')}<div><strong>${safe(p.venue)}</strong><span>Meet at a public venue</span></div></div><div>${icon('user')}<div><strong>${p.size-p.spots} going · ${p.spots} ${p.spots===1?'spot':'spots'} open</strong><span>Small group · ${p.size} people maximum</span></div></div></div><h2>The plan</h2><ul><li><strong>Meet:</strong> ${safe(p.meet)}</li><li><strong>Bring:</strong> ${safe(p.bring)}</li><li><strong>Cost:</strong> Everyone covers their own venue costs unless the group agrees otherwise.</li></ul></article><div class="side-stack"><section class="panel"><h2>${mine?'Your plan':'Meet your host'}</h2><div class="host-large">${avatar(p)}<div><strong>${safe(p.host)}</strong><span>Hosting a public activity</span></div></div><div class="trust-note">${icon('shield')} Take a moment to review the place and plan. Share your plans with someone you trust and meet at the listed public venue.</div>${mine?`<button class="button full" data-chat="${p.id}">Open group chat</button>`:joined?`<button class="button full" data-chat="${p.id}">Open group chat</button>`:requested?`<button class="button full" disabled>Request sent</button><p class="small muted">You’ll see this in My plans until the host responds.</p>`:`<button class="button full" data-request="${p.id}">Ask to join</button><p class="small muted">The host will review your request before chat opens.</p>`}</section>${mine?`<section class="panel"><h2>Join requests</h2>${incoming?`<div class="host-large"><span class="avatar pink">NA</span><div><strong>Nina A.</strong><span>Interested in joining · sample request</span></div></div><button class="button full" data-hostaccept="${p.id}">Accept Nina</button>`:`<p class="small muted">No requests are waiting. When someone asks to join, review their profile here.</p>`}</section>`:''}<section class="panel"><h2>Before you meet</h2><p class="small muted">Keep first meetups in public places. You can leave a plan, and report anything that feels wrong.</p><button class="button text" data-report="${p.id}">${icon('flag')} Report this plan</button></section></div></div>`}
function plansPage(){let ids=state.planTab==='Upcoming'?[...new Set([...state.joined,...state.requests,...state.plans.filter(p=>p.host==='You').map(p=>p.id)])]:state.completed;let items=ids.map(id=>plan(id)).filter(Boolean);return `<div class="page-head"><div><h1>My plans</h1><p>Your next steps, all in one place.</p></div></div><div class="tabs"><button class="${state.planTab==='Upcoming'?'active':''}" data-tab="Upcoming">Upcoming</button><button class="${state.planTab==='Past'?'active':''}" data-tab="Past">Past</button></div>${items.length?items.map(p=>{let joined=state.joined.includes(p.id),req=state.requests.includes(p.id),done=state.completed.includes(p.id),mine=p.host==='You';return `<div class="list-item"><span class="avatar ${p.tone||''}">${safe(p.initials)}</span><div class="grow"><h3>${safe(p.title)}</h3><p>${safe(p.date)} · ${safe(p.time)} · ${safe(p.venue)}</p></div><span class="status ${done?'confirmed':joined||mine?'confirmed':'pending'}">${done?'Completed':mine?'Hosting':joined?'Confirmed':req?'Request pending':''}</span><button class="button secondary" data-detail="${p.id}">Details</button>${joined||mine?`<button class="button" data-chat="${p.id}">Chat</button>`:''}</div>`}).join(''):`<div class="empty"><h3>${state.planTab==='Past'?'No past plans yet':'Nothing on your calendar yet'}</h3><p>${state.planTab==='Past'?'Your completed meetups will appear here.':'Find a plan that makes you want to go.'}</p><button class="button" data-nav="explore">Explore plans</button></div>`}${state.planTab==='Upcoming'&&state.requests.length?`<div class="notice">Demo tip: Open Profile → Demo controls to accept a pending request and try the confirmed plan flow.</div>`:''}`}
function create(){return `<button class="back" data-nav="explore">${icon('back')} Back to explore</button><div class="page-head"><div><h1>Make a plan</h1><p>Give people a clear reason to say “I’m in.”</p></div></div><div class="form-layout"><form id="create-form" class="panel"><div class="field"><label for="activity">What do you want to do?</label><input id="activity" name="title" required maxlength="80" placeholder="e.g. Try the Saturday beginner swim class"><small>Make it specific enough to picture the outing.</small></div><div class="two-fields"><div class="field"><label for="category">Category</label><select id="category" name="category"><option>Fitness</option><option>Outings</option><option>Learning</option></select></div><div class="field"><label for="size">Group size</label><select id="size" name="size"><option value="2">Me + 1 person</option><option value="3">3 people</option><option value="4">4 people</option><option value="5">5 people</option></select></div></div><div class="field"><label for="venue">Public venue</label><input id="venue" name="venue" required maxlength="90" placeholder="Venue name and neighbourhood"></div><div class="two-fields"><div class="field"><label for="date">Date</label><input id="date" name="date" type="date" required></div><div class="field"><label for="time">Time</label><input id="time" name="time" type="time" required></div></div><div class="field"><label for="intro">What should people know?</label><textarea id="intro" name="intro" required maxlength="320" placeholder="The pace, vibe, and why you'd like company"></textarea></div><div class="two-fields"><div class="field"><label for="meet">Where exactly will you meet?</label><input id="meet" name="meet" required placeholder="e.g. At the front entrance"></div><div class="field"><label for="bring">What should they bring?</label><input id="bring" name="bring" placeholder="e.g. Comfortable shoes"></div></div><button class="button orange" type="submit">Publish plan ${icon('arrow')}</button></form><aside class="panel form-intro"><h2>A good plan feels easy to join.</h2><p>Specific details help someone decide, show up, and find you when they arrive.</p><ol><li>Choose a public venue with a clear meeting point.</li><li>Say whether it’s beginner friendly and mention likely costs.</li><li>Keep the group small enough to coordinate easily.</li></ol></aside></div>`}
function chat(){let p=plan(state.chatId),available=state.plans.filter(x=>state.joined.includes(x.id)||x.host==='You');if(!available.length)return `<div class="page-head"><div><h1>Messages</h1><p>Chat opens once a plan is confirmed.</p></div></div><div class="empty"><h3>No conversations yet</h3><p>Join a plan or create one to start coordinating.</p><button class="button" data-nav="explore">Explore plans</button></div>`;if(!available.some(x=>x.id===p?.id)){p=available[0];state.chatId=p.id}let messages=state.messages[p.id]||[];let checked=state.checkins.includes(p.id),done=state.completed.includes(p.id);return `<div class="page-head"><div><h1>Messages</h1><p>Make the details easy before you meet.</p></div></div><div class="chat-layout"><div class="panel chat-list">${available.map(x=>`<button class="chat-choice ${p.id===x.id?'active':''}" data-chat="${x.id}"><strong>${safe(x.title)}</strong><span>${safe(x.date)} · ${safe(x.time)}</span></button>`).join('')}</div><div class="panel chat-panel"><div class="chat-header"><strong>${safe(p.title)}</strong><small>${safe(p.venue)} · ${safe(p.date)} at ${safe(p.time)}</small></div><div class="messages" id="messages"><div class="notice">Group chat is for plan details. Meet at the public venue and trust your judgement.</div>${messages.map(m=>`<div class="bubble ${m.mine?'mine':''}">${safe(m.text)}<small>${safe(m.time)}</small></div>`).join('')}</div><form id="message-form" class="chat-compose"><input name="message" aria-label="Message" required maxlength="500" placeholder="Ask about the meeting point…"><button class="button">Send</button></form></div></div><div style="height:16px"></div><section class="panel"><h2>On the day</h2><p class="small muted">Confirm when you reach the meeting point. Afterward, mark the plan complete.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="button secondary" data-checkin="${p.id}" ${checked?'disabled':''}>${icon('check')} ${checked?'Checked in':'I’m here'}</button><button class="button secondary" data-complete="${p.id}" ${done?'disabled':''}>${done?'Plan completed':'Mark completed'}</button><button class="button text" data-report="${p.id}">${icon('flag')} Report</button></div></section>`}
function profile(){return `<div class="page-head"><div><h1>Your profile</h1><p>A little context helps people feel comfortable saying yes.</p></div></div><div class="detail-layout"><section class="panel"><div class="host-large"><span class="avatar" style="width:65px;height:65px">YO</span><div><strong>You</strong><span>Kampala · enjoys swimming, coffee and walks</span></div></div><div class="detail-meta"><div>${icon('shield')}<div><strong>Public meetups</strong><span>Keep first plans at public venues and agree on a clear meeting point.</span></div></div><div>${icon('check')}<div><strong>Show-up history</strong><span>Appears here after you complete plans. No rating is claimed in this demo.</span></div></div></div><h2>About you</h2><p class="muted">“Trying to spend more weekends doing things instead of thinking about them.”</p></section><section class="side-stack"><div class="panel"><h2>Safety tools</h2><p class="small muted">You can report a plan from its detail page or group chat. If you feel unsafe, leave and contact local help.</p><button class="button secondary" data-nav="explore">Browse public plans</button></div><div class="panel"><h2>Demo controls</h2><p class="small muted">Try the full flow without another account. Accepting a request simulates a host response.</p><button class="button full" data-accept ${state.requests.length?'':'disabled'}>Accept my pending request</button><button class="button text" data-reset>Reset sample data</button></div></section></div>`}
function render(){root.innerHTML=chrome(({explore,detail,plans:plansPage,create,chat,profile}[state.screen]||explore)());document.title=`${state.screen[0].toUpperCase()+state.screen.slice(1)} · Along`}
root.addEventListener('click',e=>{let el=e.target.closest('[data-nav],[data-detail],[data-filter],[data-tab],[data-request],[data-chat],[data-checkin],[data-complete],[data-report],[data-accept],[data-hostaccept],[data-reset]');if(!el)return;if(el.dataset.nav){nav(el.dataset.nav)}else if(el.dataset.detail){state.detail=Number(el.dataset.detail);nav('detail')}else if(el.dataset.filter){state.filter=el.dataset.filter;render()}else if(el.dataset.tab){state.planTab=el.dataset.tab;render()}else if(el.dataset.request){let id=Number(el.dataset.request);if(!state.requests.includes(id)){state.requests.push(id);save()}toast('Request sent. You can track it in My plans.')}else if(el.dataset.chat){state.chatId=Number(el.dataset.chat);nav('chat')}else if(el.dataset.checkin){state.checkins.push(Number(el.dataset.checkin));save();toast('Check-in recorded for this demo.')}else if(el.dataset.complete){let id=Number(el.dataset.complete);state.completed.push(id);save();toast('Plan completed. Thanks for showing up!')}else if(el.dataset.report){let reason=prompt('What would you like to report about this plan?');if(reason?.trim())toast('Report recorded in this demo.')}else if(el.hasAttribute('data-accept')){let id=state.requests.shift();if(id){state.joined.push(id);let p=plan(id);p.spots=Math.max(0,p.spots-1);state.messages[id]=[{mine:false,text:`Hi! Happy you can join. Let’s meet ${p.meet.toLowerCase()}.`,time:'Just now'}];state.chatId=id;save();toast('Request accepted. Group chat is ready.')}}else if(el.dataset.hostaccept){let id=Number(el.dataset.hostaccept),p=plan(id);state.hostRequests=state.hostRequests.filter(x=>x!==id);p.spots=Math.max(0,p.spots-1);state.messages[id]=[{mine:false,text:'Hi! Thanks for accepting me. I’ll be there a few minutes early.',time:'Just now'}];save();toast('Nina is in. The group chat is ready.')}else if(el.hasAttribute('data-reset')){localStorage.removeItem('along-demo');location.reload()}}, { signal: controller.signal });
root.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;let pos=e.target.selectionStart;render();let search=document.getElementById('search');search.focus();search.setSelectionRange(pos,pos)}}, { signal: controller.signal });
root.addEventListener('submit',e=>{if(e.target.id==='create-form'){e.preventDefault();let f=new FormData(e.target),d=new Date(`${f.get('date')}T${f.get('time')}`);if(Number.isNaN(d.getTime()))return toast('Choose a valid date and time.');if(d<new Date())return toast('Choose a future date for your plan.');let p={id:Date.now(),category:f.get('category'),title:f.get('title').trim(),venue:f.get('venue').trim(),date:d.toLocaleDateString('en-UG',{weekday:'short',day:'numeric',month:'short'}),time:d.toLocaleTimeString('en-UG',{hour:'numeric',minute:'2-digit'}),spots:Number(f.get('size'))-1,size:Number(f.get('size')),host:'You',initials:'YO',tone:'',intro:f.get('intro').trim(),bring:f.get('bring').trim()||'Whatever you need for the activity',meet:f.get('meet').trim(),status:'open'};state.plans.unshift(p);state.hostRequests.push(p.id);state.detail=p.id;save();toast('Your plan is live. A sample join request is ready to review.');nav('detail')}else if(e.target.id==='message-form'){e.preventDefault();let input=e.target.elements.message,text=input.value.trim();if(!text)return;let id=state.chatId;state.messages[id]??=[];state.messages[id].push({mine:true,text,time:'Just now'});save();render();document.getElementById('messages')?.scrollTo(0,99999)}}, { signal: controller.signal });
render();
return () => controller.abort();
}

